"""Generate the Continuum formula and its resolved Python resources from PyPI."""

import json
import subprocess
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

FORMULA = Path(__file__).resolve().parents[2] / "Formula" / "continuum.rb"
TEMPLATE = '''\
# Generated by .github/scripts/update_formula.py from PyPI party-continuum; edits are overwritten.
class Continuum < Formula
  include Language::Python::Virtualenv

  desc "Static change impact of a checkout: dependents, reach and tests to run"
  homepage "https://pypi.org/project/party-continuum/"
  url "@URL@"
  sha256 "@SHA256@"

  depends_on "python@3.13"

@RESOURCES@
  def install
    virtualenv_install_with_resources
  end

  test do
    assert_match "usage: continuum", shell_output("#{bin}/continuum --help")
    system libexec/"bin/python", "-c", "import httpx; from party_continuum.api import Client; c = Client('https://example.invalid', 'unused'); assert isinstance(c.http, httpx.Client); c.close()"
  end
end
'''


def metadata(name, version=None):
    path = urllib.parse.quote(name, safe="")
    if version is not None:
        path += "/" + urllib.parse.quote(version, safe="")
    with urllib.request.urlopen(f"https://pypi.org/pypi/{path}/json", timeout=30) as response:
        return json.load(response)


def sdist(release):
    values = [item for item in release["urls"] if item["packagetype"] == "sdist"]
    if len(values) != 1:
        raise ValueError(f"{release['info']['name']}: expected one source distribution")
    return values[0]


def resources(version):
    # pip resolves the published distribution, including transitive dependencies;
    # no project code is installed or executed during formula generation.
    result = subprocess.run(
        [sys.executable, "-m", "pip", "install", "--dry-run", "--ignore-installed",
         "--disable-pip-version-check", "--quiet", "--only-binary=:all:",
         "--python-version", "3.13", "--report", "-", f"party-continuum=={version}"],
        capture_output=True, text=True, check=True,
    )
    packages = json.loads(result.stdout)["install"]
    blocks = []
    for package in sorted(packages, key=lambda item: item["metadata"]["name"].lower()):
        info = package["metadata"]
        if info["name"].lower().replace("_", "-") == "party-continuum":
            continue
        source = sdist(metadata(info["name"], info["version"]))
        blocks.append(
            f'  resource "{info["name"]}" do\n'
            f'    url "{source["url"]}"\n'
            f'    sha256 "{source["digests"]["sha256"]}"\n'
            '  end\n'
        )
    if not any('resource "httpx"' in block for block in blocks):
        raise ValueError("Published CLI does not declare its HTTPX transport")
    return "\n".join(blocks)


def main():
    try:
        release = metadata("party-continuum")
    except urllib.error.HTTPError as error:
        if error.code == 404:
            print("party-continuum is not on PyPI yet", file=sys.stderr)
            return 0
        raise
    source = sdist(release)
    # Once a release's tested resources are pinned, avoid changing them during a
    # scheduled check merely because an unrelated dependency released again.
    if FORMULA.exists():
        current = FORMULA.read_text()
        if (f'url "{source["url"]}"' in current
                and f'sha256 "{source["digests"]["sha256"]}"' in current
                and "virtualenv_install_with_resources" in current):
            return 0
    version = release["info"]["version"]
    text = (TEMPLATE.replace("@URL@", source["url"])
            .replace("@SHA256@", source["digests"]["sha256"])
            .replace("@RESOURCES@", resources(version)))
    FORMULA.parent.mkdir(parents=True, exist_ok=True)
    FORMULA.write_text(text)
    print(version)
    return 0


if __name__ == "__main__":
    sys.exit(main())
